using Mono.Cecil;
using Mono.Cecil.Cil;
using System.Reflection.PortableExecutable;
using System.Security.Cryptography;
using System.Text.Json;
namespace WinrtSecondPass;
static class DeepVerifier
{
 static readonly string[] Names=["Microsoft.Windows.SDK.NET","WinRT.Runtime"];
 static IEnumerable<TypeDefinition> Types(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var x in Types(n))yield return x;}
 static IEnumerable<TypeDefinition> Types(ModuleDefinition m)=>m.Types.SelectMany(Types);
 static string Hash(byte[] b)=>Convert.ToHexString(SHA256.HashData(b)).ToLowerInvariant();
 static void Write(string p,object v)=>File.WriteAllText(p,JsonSerializer.Serialize(v,new JsonSerializerOptions{WriteIndented=true}));
 static string Scope(TypeReference t){if(t is FunctionPointerType)return "function-pointer";if(t is TypeSpecification ts)return Scope(ts.ElementType);if(t is GenericParameter)return "generic-parameter";var s=t.Scope is AssemblyNameReference a?a.Name:t.Scope is ModuleDefinition m?m.Assembly.Name.Name:t.Scope?.Name??"";if(s is "mscorlib" or "netstandard" or "System.Runtime" or "Microsoft.Win32.Primitives"||s.StartsWith("System.")){try{return t.Resolve()?.Module.Assembly.Name.Name??s;}catch(AssemblyResolutionException){}}return s;}
 static string Fmt(object? o,MethodDefinition m)=>o switch{null=>"",Instruction i=>"@"+m.Body.Instructions.IndexOf(i),Instruction[] a=>string.Join(",",a.Select(i=>"@"+m.Body.Instructions.IndexOf(i))),TypeReference t=>t.FullName+"["+Scope(t)+"]",MemberReference r=>r.FullName+"["+Scope(r.DeclaringType)+"]",VariableDefinition v=>"V"+v.Index+":"+v.VariableType.FullName,ParameterDefinition p=>"P"+p.Index+":"+p.ParameterType.FullName,float f=>f.ToString("R",System.Globalization.CultureInfo.InvariantCulture),double d=>d.ToString("R",System.Globalization.CultureInfo.InvariantCulture),_=>o.ToString()??""};
 static string Canon(MethodDefinition m)=>string.Join("\n",new[]{m.FullName,"arity:"+m.GenericParameters.Count,m.Attributes.ToString(),m.ImplAttributes.ToString(),m.HasPInvokeInfo?m.PInvokeInfo.Module.Name+":"+m.PInvokeInfo.EntryPoint+":"+m.PInvokeInfo.Attributes:"",m.HasBody?"init:"+m.Body.InitLocals:"no-body"}.Concat(!m.HasBody?[]:m.Body.Variables.Select(v=>"var:"+v.VariableType.FullName).Concat(m.Body.Instructions.Select(i=>i.OpCode+" "+Fmt(i.Operand,m))).Concat(m.Body.ExceptionHandlers.Select(h=>"eh:"+h.HandlerType+":"+h.CatchType?.FullName+":"+Fmt(h.TryStart,m)+":"+Fmt(h.TryEnd,m)+":"+Fmt(h.HandlerStart,m)+":"+Fmt(h.HandlerEnd,m)+":"+Fmt(h.FilterStart,m)))));
 static AssemblyDefinition Read(string p){var r=new DefaultAssemblyResolver();r.AddSearchDirectory(Path.GetDirectoryName(p)!);r.AddSearchDirectory(System.Runtime.InteropServices.RuntimeEnvironment.GetRuntimeDirectory());return AssemblyDefinition.ReadAssembly(p,new ReaderParameters{AssemblyResolver=r});}
 public static void IL(string before,string after,string output){var failures=new List<string>();var results=new List<object>();foreach(var n in Names){using var a=Read(Path.Combine(before,n+".dll"));using var b=Read(Path.Combine(after,n+".dll"));var at=Types(a.MainModule).ToDictionary(t=>t.FullName);int count=0;var removed=new List<string>();foreach(var t in Types(b.MainModule)){if(!at.TryGetValue(t.FullName,out var ot)){failures.Add("new type "+t.FullName);continue;}foreach(var m in t.Methods){count++;var om=ot.Methods.FirstOrDefault(x=>x.FullName==m.FullName&&x.GenericParameters.Count==m.GenericParameters.Count);if(om==null||Canon(om)!=Canon(m))failures.Add("retained method IL "+m.FullName);}}var bt=Types(b.MainModule).ToDictionary(t=>t.FullName);foreach(var t in at.Values){if(!bt.TryGetValue(t.FullName,out var nt)){removed.Add(t.FullName);continue;}foreach(var m in t.Methods)if(!nt.Methods.Any(x=>x.FullName==m.FullName&&x.GenericParameters.Count==m.GenericParameters.Count))removed.Add(m.FullName);}
 var ar=a.MainModule.Resources.OfType<EmbeddedResource>().ToDictionary(r=>r.Name,r=>Hash(r.GetResourceData()));var br=b.MainModule.Resources.OfType<EmbeddedResource>().ToDictionary(r=>r.Name,r=>Hash(r.GetResourceData()));if(!ar.OrderBy(p=>p.Key).SequenceEqual(br.OrderBy(p=>p.Key)))failures.Add(n+" embedded resources changed");results.Add(new{name=n,methods=count,beforeTypes=at.Count,afterTypes=bt.Count,removed,resourcesBefore=ar,resourcesAfter=br});}
 Write(output,new{status=failures.Count==0?"passed":"failed",normalization="Only framework forwarded definition scope and meaningless FunctionPointerType.Scope are normalized; function pointer full signatures, calling convention and all original IL opcodes/operands/locals/EH/PInvoke retained",results,failures});Console.WriteLine($"EXACT IL {failures.Count} differences");if(failures.Count>0)Environment.ExitCode=1;}
 public static void DataAudit(string before,string after,string output){using var a=Read(Path.Combine(before,"Microsoft.Windows.SDK.NET.dll"));using var b=Read(Path.Combine(after,"Microsoft.Windows.SDK.NET.dll"));var bt=Types(b.MainModule).ToDictionary(t=>t.FullName);var removed=new List<object>();var failures=new List<string>();var refs=new HashSet<string>();foreach(var t in Types(a.MainModule))foreach(var m in t.Methods.Where(m=>m.HasBody))foreach(var i in m.Body.Instructions)if(i.Operand is FieldReference fr)refs.Add(fr.FullName);
 foreach(var t in Types(a.MainModule)){if(!bt.TryGetValue(t.FullName,out var nt)){failures.Add("removed type "+t.FullName);continue;}foreach(var f in t.Fields){if(nt.Fields.Any(x=>x.FullName==f.FullName))continue;bool container=t.FullName=="<PrivateImplementationDetails>"&&t.IsNotPublic&&t.IsSealed&&t.CustomAttributes.Any(c=>c.AttributeType.FullName=="System.Runtime.CompilerServices.CompilerGeneratedAttribute");bool data=f.IsStatic&&f.IsInitOnly&&f.InitialValue.Length>0&&(f.Attributes&FieldAttributes.HasFieldRVA)!=0&&!f.IsPublic;bool allowed=container&&data&&!refs.Contains(f.FullName);if(!allowed)failures.Add("non-data-or-referenced removal "+f.FullName);removed.Add(new{field=f.FullName,attributes=f.Attributes.ToString(),container=t.FullName,containerAttributes=t.Attributes.ToString(),containerCustomAttributes=t.CustomAttributes.Select(c=>c.AttributeType.FullName).ToArray(),rvaBytes=f.InitialValue.Length,rvaSha256=Hash(f.InitialValue),constant=f.HasConstant?f.Constant:null,ilReferencePresent=refs.Contains(f.FullName),compilerDataIsolation=container&&data,allowed});}}
 var removedMembers=new List<string>();foreach(var oldType in Types(a.MainModule)){if(!bt.TryGetValue(oldType.FullName,out var newType))continue;foreach(var m in oldType.Methods)if(!newType.Methods.Any(n=>n.FullName==m.FullName&&n.GenericParameters.Count==m.GenericParameters.Count))removedMembers.Add("method "+m.FullName);foreach(var q in oldType.Properties)if(!newType.Properties.Any(n=>n.FullName==q.FullName))removedMembers.Add("property "+q.FullName);foreach(var q in oldType.Events)if(!newType.Events.Any(n=>n.FullName==q.FullName))removedMembers.Add("event "+q.FullName);}failures.AddRange(removedMembers);var privateType=Types(a.MainModule).Single(t=>t.FullName=="<PrivateImplementationDetails>");var inbound=new List<object>();foreach(var tr in a.MainModule.GetTypeReferences().Where(tr=>tr.FullName==privateType.FullName))inbound.Add(new{kind="TypeRef",name=tr.FullName});
 Write(output,new{status=failures.Count==0?"structural-data-check-passed-dynamic-proof-pending":"failed",removedFieldCount=removed.Count,removedMethodsPropertiesEvents=removedMembers,removedFields=removed,failures,compilerContainerInterfaces=privateType.Interfaces.Select(i=>i.InterfaceType.FullName).ToArray(),compilerContainerMethods=privateType.Methods.Select(m=>m.FullName).ToArray(),inbound,limitation="Nonpublic compiler RVA shape plus zero IL tokens are necessary structural evidence, not a standalone proof against arbitrary reflection. Dynamic projection/serializer reachability must be evaluated separately."});Console.WriteLine($"DATA AUDIT {removed.Count} removals, {failures.Count} non-data/referenced failures");if(failures.Count>0)Environment.ExitCode=1;}
 public static void RepackSdk(string before,string after){Directory.CreateDirectory(after);foreach(var path in Directory.GetFiles(before,"*",SearchOption.AllDirectories)){string target=Path.Combine(after,Path.GetRelativePath(before,path));Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.Copy(path,target,true);}using var a=Read(Path.Combine(before,"Microsoft.Windows.SDK.NET.dll"));a.Write(Path.Combine(after,"Microsoft.Windows.SDK.NET.dll"),new WriterParameters{WriteSymbols=false});Console.WriteLine("SDK repack preserving all original type/member definitions");}
 public static void Signatures(string root,string output){var rows=new List<object>();foreach(var n in Names){var p=Path.Combine(root,n+".dll");var bytes=File.ReadAllBytes(p);using var pe=new PEReader(new MemoryStream(bytes));using var a=Read(p);bool? valid=null;string? error=null;try{valid=DevelopmentSigning.Verify(bytes);}catch(Exception e){error=e.GetType().Name+": "+e.Message;}var cert=pe.PEHeaders.PEHeader!.CertificateTableDirectory;rows.Add(new{name=n,sha256=Hash(bytes),bytes=bytes.Length,assemblyIdentity=a.Name.FullName,publicKeyToken=Convert.ToHexString(a.Name.PublicKeyToken).ToLowerInvariant(),strongNameSignedFlag=pe.PEHeaders.CorHeader!.Flags.HasFlag(CorFlags.StrongNameSigned),strongNameSignatureBytes=pe.PEHeaders.CorHeader!.StrongNameSignatureDirectory.Size,strongNameCryptographicVerification=valid,verificationError=error,sections=pe.PEHeaders.SectionHeaders.Select(s=>new{s.Name,s.VirtualSize,s.SizeOfRawData,s.PointerToRawData}).ToArray(),metadataBytes=pe.PEHeaders.CorHeader!.MetadataDirectory.Size,embeddedAuthenticodeCertificateBytes=cert.Size,embeddedCertificateSha256=cert.Size>0?Hash(bytes[cert.RelativeVirtualAddress..(cert.RelativeVirtualAddress+cert.Size)]):null,developmentResigned=false});}Write(output,new{assemblies=rows,networkUsed=false,scope="Strong-name cryptography and embedded certificate preservation facts; no online Authenticode trust/revocation query"});Console.WriteLine("SIGNATURE facts recorded");}
}



